// ***************
// Filename: i2c_top.sv
// Author: FPGA Cores 4 U
// Description: i2c_master with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map i2c_master_regs
//   (u_regs, src/include/i2c_master_regs.sv, ID "I2CM", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic i2c_master (u_core,
//   src/i2c_master.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   i2c_master_regs.json and the ports of i2c_master: regenerate after
//   changing either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module i2c_top #(
  parameter int CLK_HZ = 100_000_000,
  parameter int SCL_HZ = 100_000,
  parameter int FIFO_DEPTH = 512
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  input  logic [7:0]  s_axis_tdata,
  input  logic        s_axis_tvalid,
  output logic        s_axis_tready,
  input  logic        s_axis_tlast,
  output logic [7:0]  m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast,
  input  logic        scl_i,
  output logic        scl_o,
  output logic        scl_t,
  input  logic        sda_i,
  output logic        sda_o,
  output logic        sda_t
);
  // register ports between the register map and the logic
  logic [3:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [6:0] cfg_addr;
  logic [15:0] cfg_len;
  logic [15:0] cfg_div;
  logic [31:0] cfg_status;
  logic cfg_status_wr;
  logic [31:0] sts_status;

  i2c_master_regs #(
    .DIV_RST((CLK_HZ / (4 * SCL_HZ)) - 1)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(cfg_ctrl_wr),
    .addr_o(cfg_addr),
    .addr_wr_o(),
    .len_o(cfg_len),
    .len_wr_o(),
    .div_o(cfg_div),
    .div_wr_o(),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status)
  );
  i2c_master #(
    .CLK_HZ(CLK_HZ),
    .SCL_HZ(SCL_HZ),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis_tdata,
    .s_axis_tvalid,
    .s_axis_tready,
    .s_axis_tlast,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .scl_i,
    .scl_o,
    .scl_t,
    .sda_i,
    .sda_o,
    .sda_t,
    .cfg_ctrl,
    .cfg_ctrl_wr,
    .cfg_addr,
    .cfg_len,
    .cfg_div,
    .cfg_status,
    .cfg_status_wr,
    .sts_status
  );
endmodule
